import { Component, OnInit } from '@angular/core';
import { AbstractControl, FormBuilder, FormGroup, ValidationErrors, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ProductService } from '../../services/product.service';
import { AuthService } from '../../services/auth.service';
import { Category } from '../../models/product.model';

@Component({
  selector: 'app-product-submit',
  templateUrl: './product-submit.component.html',
  styleUrls: ['./product-submit.component.css']
})
export class ProductSubmitComponent implements OnInit {
  submitForm!: FormGroup;
  isLoading = false;
  errorMessage = '';
  successMessage = '';

  categories: Category[] = [];

  constructor(
    private fb: FormBuilder,
    private productService: ProductService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.productService.getCategories().subscribe({
      next: (cats) => { this.categories = cats; },
      error: () => { this.errorMessage = 'Could not load categories. Please refresh.'; }
    });

    this.submitForm = this.fb.group({
      productName: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(100)]],
      description: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(500)]],
      imageUrl: ['', [Validators.required, Validators.pattern(/^https?:\/\/.+/)]],
      startingPrice: [null, [Validators.required, Validators.min(1)]],
      categoryId: [null, [Validators.required]],
      auctionStartDate: ['', [Validators.required]],
      auctionEndDate: ['', [Validators.required]],
      termsAccepted: [false, [Validators.requiredTrue]]
    }, { validators: this.dateRangeValidator });
  }

  dateRangeValidator(group: AbstractControl): ValidationErrors | null {
    const start = group.get('auctionStartDate')?.value as string;
    const end = group.get('auctionEndDate')?.value as string;
    if (!start || !end) return null;
    if (new Date(start) < new Date()) return { startInPast: true };
    if (new Date(end) <= new Date(start)) return { endBeforeStart: true };
    return null;
  }

  get productNameCtrl() { return this.submitForm.get('productName'); }
  get descriptionCtrl() { return this.submitForm.get('description'); }
  get imageUrlCtrl() { return this.submitForm.get('imageUrl'); }
  get startingPriceCtrl() { return this.submitForm.get('startingPrice'); }
  get categoryIdCtrl() { return this.submitForm.get('categoryId'); }
  get auctionStartDateCtrl() { return this.submitForm.get('auctionStartDate'); }
  get auctionEndDateCtrl() { return this.submitForm.get('auctionEndDate'); }
  get termsAcceptedCtrl() { return this.submitForm.get('termsAccepted'); }

  onSubmit(): void {
    if (this.submitForm.invalid) {
      this.submitForm.markAllAsTouched();
      return;
    }

    const sellerId = this.authService.getUserId();
    if (!sellerId) {
      this.errorMessage = 'Seller ID not found. Please set your User ID in the Wallet page first.';
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';
    this.successMessage = '';

    const formVal = this.submitForm.value as {
      productName: string;
      description: string;
      imageUrl: string;
      startingPrice: number;
      categoryId: number;
    };

    this.productService.submitProduct(sellerId, {
      productName: formVal.productName,
      description: formVal.description,
      imageUrl: formVal.imageUrl,
      startingPrice: formVal.startingPrice,
      categoryId: formVal.categoryId
    }).subscribe({
      next: () => {
        this.isLoading = false;
        this.successMessage = 'Product submitted for review! Your item will be reviewed by our team within 24–48 hours.';
        this.submitForm.reset();
        setTimeout(() => void this.router.navigate(['/products']), 2500);
      },
      error: (err: { status: number; error?: { message?: string } }) => {
        this.isLoading = false;
        if (err.status === 0) {
          this.errorMessage = 'Cannot connect to server. Please try again later.';
        } else if (err.status === 403) {
          this.errorMessage = 'You are not authorized to submit products.';
        } else {
          this.errorMessage = err.error?.message || 'Failed to submit product. Please try again.';
        }
      }
    });
  }

  get imagePreviewUrl(): string {
    const val = this.imageUrlCtrl?.value as string;
    return val && /^https?:\/\/.+/.test(val) ? val : '';
  }
}
<div class="page-wrapper">
  <div class="container">
    <div class="row justify-content-center">
      <div class="col-lg-8">
        <!-- Page Title -->
        <div class="d-flex align-items-center mb-4">
          <i class="bi bi-plus-circle-fill text-primary fs-3 me-3"></i>
          <div>
            <h3 class="fw-bold mb-0">Submit a Product</h3>
            <p class="text-muted mb-0 small">Your product will be reviewed by an admin before listing.</p>
          </div>
        </div>

        <!-- Alerts -->
        <div class="alert alert-danger d-flex align-items-center gap-2" *ngIf="errorMessage">
          <i class="bi bi-exclamation-triangle-fill"></i>
          <span>{{ errorMessage }}</span>
        </div>
        <div class="alert alert-success d-flex align-items-center gap-2" *ngIf="successMessage">
          <i class="bi bi-check-circle-fill"></i>
          <span>{{ successMessage }}</span>
        </div>

        <div class="row g-4">
          <!-- Form -->
          <div class="col-md-7">
            <div class="card p-4">
              <form [formGroup]="submitForm" (ngSubmit)="onSubmit()" novalidate>
                <!-- Product Name -->
                <div class="mb-3">
                  <label class="form-label fw-semibold">Product Name <span class="text-danger">*</span></label>
                  <input
                    type="text"
                    class="form-control"
                    formControlName="productName"
                    placeholder="e.g., Vintage Rolex Submariner"
                    [class.is-invalid]="productNameCtrl?.invalid && productNameCtrl?.touched"
                  />
                  <div class="invalid-feedback">
                    <span *ngIf="productNameCtrl?.errors?.['required']">Product name is required.</span>
                    <span *ngIf="productNameCtrl?.errors?.['minlength']">At least 3 characters required.</span>
                    <span *ngIf="productNameCtrl?.errors?.['maxlength']">Max 100 characters allowed.</span>
                  </div>
                </div>

                <!-- Description -->
                <div class="mb-3">
                  <label class="form-label fw-semibold">Description <span class="text-danger">*</span></label>
                  <textarea
                    class="form-control"
                    formControlName="description"
                    rows="4"
                    placeholder="Describe your product in detail..."
                    [class.is-invalid]="descriptionCtrl?.invalid && descriptionCtrl?.touched"
                  ></textarea>
                  <div class="invalid-feedback">
                    <span *ngIf="descriptionCtrl?.errors?.['required']">Description is required.</span>
                    <span *ngIf="descriptionCtrl?.errors?.['minlength']">At least 10 characters required.</span>
                    <span *ngIf="descriptionCtrl?.errors?.['maxlength']">Max 500 characters allowed.</span>
                  </div>
                  <small class="text-muted">{{ descriptionCtrl?.value?.length || 0 }}/500</small>
                </div>

                <!-- Image URL -->
                <div class="mb-3">
                  <label class="form-label fw-semibold">Image URL <span class="text-danger">*</span></label>
                  <input
                    type="url"
                    class="form-control"
                    formControlName="imageUrl"
                    placeholder="https://example.com/image.jpg"
                    [class.is-invalid]="imageUrlCtrl?.invalid && imageUrlCtrl?.touched"
                  />
                  <div class="invalid-feedback">
                    <span *ngIf="imageUrlCtrl?.errors?.['required']">Image URL is required.</span>
                    <span *ngIf="imageUrlCtrl?.errors?.['pattern']">Must be a valid HTTP/HTTPS URL.</span>
                  </div>
                </div>

                <!-- Starting Price -->
                <div class="mb-3">
                  <label class="form-label fw-semibold">Starting Price (&#x20B9;) <span class="text-danger">*</span></label>
                  <div class="input-group">
                    <span class="input-group-text fw-bold">&#x20B9;</span>
                    <input
                      type="number"
                      class="form-control"
                      formControlName="startingPrice"
                      placeholder="e.g., 5000"
                      min="1"
                      [class.is-invalid]="startingPriceCtrl?.invalid && startingPriceCtrl?.touched"
                    />
                    <div class="invalid-feedback">
                      <span *ngIf="startingPriceCtrl?.errors?.['required']">Starting price is required.</span>
                      <span *ngIf="startingPriceCtrl?.errors?.['min']">Price must be at least ₹1.</span>
                    </div>
                  </div>
                </div>

                <!-- Category -->
                <div class="mb-4">
                  <label class="form-label fw-semibold">Category <span class="text-danger">*</span></label>
                  <select
                    class="form-select"
                    formControlName="categoryId"
                    [class.is-invalid]="categoryIdCtrl?.invalid && categoryIdCtrl?.touched"
                  >
                    <option [ngValue]="null" disabled>-- Select a category --</option>
                    <option *ngFor="let cat of categories" [ngValue]="cat.categoryId">
                      {{ cat.categoryName }}
                    </option>
                  </select>
                  <div class="invalid-feedback">Please select a category.</div>
                </div>

                <!-- Auction Start Date -->
                <div class="mb-3">
                  <label class="form-label fw-semibold">Auction Start Date & Time <span class="text-danger">*</span></label>
                  <input
                    type="datetime-local"
                    class="form-control"
                    formControlName="auctionStartDate"
                    [class.is-invalid]="auctionStartDateCtrl?.invalid && auctionStartDateCtrl?.touched"
                  />
                  <div class="invalid-feedback">Please select a valid future start date.</div>
                </div>

                <!-- Auction End Date -->
                <div class="mb-3">
                  <label class="form-label fw-semibold">Auction End Date & Time <span class="text-danger">*</span></label>
                  <input
                    type="datetime-local"
                    class="form-control"
                    formControlName="auctionEndDate"
                    [class.is-invalid]="auctionEndDateCtrl?.invalid && auctionEndDateCtrl?.touched"
                  />
                  <div class="invalid-feedback">End date must be after the start date.</div>
                  <div class="text-danger small mt-1" *ngIf="submitForm.errors?.['startInPast'] && auctionStartDateCtrl?.touched">
                    Start date cannot be in the past.
                  </div>
                  <div class="text-danger small mt-1" *ngIf="submitForm.errors?.['endBeforeStart'] && auctionEndDateCtrl?.touched">
                    End date must be after the start date.
                  </div>
                </div>

                <!-- Confirmation Checkbox -->
                <div class="mb-4 p-3 border rounded bg-light">
                  <div class="form-check">
                    <input
                      class="form-check-input"
                      type="checkbox"
                      id="termsAccepted"
                      formControlName="termsAccepted"
                      [class.is-invalid]="termsAcceptedCtrl?.invalid && termsAcceptedCtrl?.touched"
                    />
                    <label class="form-check-label small" for="termsAccepted">
                      I confirm that the information provided is accurate, I have the right to sell this item, and I agree to the
                      <a href="#" class="text-primary" (click)="$event.preventDefault()">Terms of Service</a> and
                      <a href="#" class="text-primary" (click)="$event.preventDefault()">Seller Agreement</a>.
                    </label>
                    <div class="invalid-feedback">You must accept the terms to submit.</div>
                  </div>
                </div>

                <!-- Submit -->
                <button type="submit" class="btn btn-primary w-100 py-2 fw-semibold" [disabled]="isLoading">
                  <span *ngIf="isLoading" class="spinner-border spinner-border-sm me-2"></span>
                  <i *ngIf="!isLoading" class="bi bi-send me-2"></i>
                  {{ isLoading ? 'Submitting...' : 'Submit for Review' }}
                </button>
              </form>
            </div>
          </div>

          <!-- Preview Panel -->
          <div class="col-md-5">
            <div class="card p-3 h-100">
              <h6 class="fw-bold mb-3 text-muted text-uppercase small">
                <i class="bi bi-eye me-2"></i>Preview
              </h6>

              <!-- Image Preview -->
              <div class="preview-image-wrapper mb-3">
                <img
                  *ngIf="imagePreviewUrl"
                  [src]="imagePreviewUrl"
                  class="img-fluid rounded"
                  alt="Preview"
                  style="height: 160px; width: 100%; object-fit: cover;"
                  (error)="$any($event.target).src = 'assets/no-image.svg'"
                />
                <div
                  *ngIf="!imagePreviewUrl"
                  class="bg-light rounded d-flex align-items-center justify-content-center"
                  style="height: 160px;">
                  <i class="bi bi-image text-muted display-4"></i>
                </div>
              </div>

              <p class="fw-bold mb-1">{{ productNameCtrl?.value || 'Product Name' }}</p>
              <p class="text-muted small mb-2">{{ descriptionCtrl?.value || 'Product description will appear here.' }}</p>

              <div class="d-flex justify-content-between align-items-center mt-auto">
                <div>
                  <p class="text-muted small mb-0">Starting Price</p>
                  <p class="fw-bold text-primary mb-0">
                    ₹{{ startingPriceCtrl?.value || '0' | number }}
                  </p>
                </div>
                <span class="badge bg-warning text-dark">PENDING</span>
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  </div>
</div>
